                  ...(target.includes('photo-marker')
                    ? {
                        imageUrl: target.includes('slow-photo-marker')
                          ? 'https://example.com/slow-photo-marker.jpg'
                          : 'https://example.com/photo-marker.jpg',
                      }
                    : {}),
